"""作业 5：由用户的八张题目截图转录并独立解答，无官方答案。"""
def get_questions(p, f, ul):
    td = 'V(S<sub>t</sub>) ← V(S<sub>t</sub>) + α[R<sub>t+1</sub> + γV(S<sub>t+1</sub>) − V(S<sub>t</sub>)]'
    ql = 'Q(S<sub>t</sub>,A<sub>t</sub>) ← Q(S<sub>t</sub>,A<sub>t</sub>) + α[R<sub>t+1</sub> + γ max<sub>a</sub> Q(S<sub>t+1</sub>,a) − Q(S<sub>t</sub>,A<sub>t</sub>)]'
    sarsa = 'Q(S<sub>t</sub>,A<sub>t</sub>) ← Q(S<sub>t</sub>,A<sub>t</sub>) + α[R<sub>t+1</sub> + γQ(S<sub>t+1</sub>,A<sub>t+1</sub>) − Q(S<sub>t</sub>,A<sub>t</sub>)]'
    return [
    (5,1,'时序差分学习的特点','下列关于时序差分方法的说法，哪个是正确的？',
    ['时序差分方法相较蒙特卡罗方法具有更高的方差','时序差分方法是一种有模型强化学习方法','时序差分方法不需要知道完整轨迹信息'],2,
    p('答案为 C。一步时序差分学习 TD(0) 观察到一次状态转移及奖励，就能结合下一状态的当前价值估计进行更新，无需等待完整回合结束。') + f(td) +
    f('TD 目标 y<sub>t</sub> = R<sub>t+1</sub> + γV(S<sub>t+1</sub>)<br>TD 误差 δ<sub>t</sub> = y<sub>t</sub> − V(S<sub>t</sub>)') +
    ul('<b>A 错：</b>典型比较中，MC 的完整回报累积了整条后续轨迹的随机性；一步 TD 使用较短的采样目标，通常方差较低，但会受到自举估计误差影响。不能把这当作所有环境下都成立的严格方差大小定理。',
       '<b>B 错：</b>经典 TD 可直接使用经验，无须显式知道环境转移概率与奖励模型，属于无模型方法。',
       '<b>C 对：</b>TD(0) 用一次转移即可构造学习目标，适合在线更新，也可用于适当条件下的持续任务。'),
    '自举：用估计更新估计',p('TD 目标中的 V(Sₜ₊₁) 是已有估计，因此称为自举（bootstrapping）。MC 的目标是完整采样回报 Gₜ，不使用后继状态的价值估计。') +
    p('“不需要完整轨迹”不等于“不需要经验”或“任意学习率都收敛”。表格型 TD 的收敛仍需要适当的任务条件、状态访问和步长安排；使用函数近似时还须额外分析稳定性。')),
    (5,2,'同策略与异策略','同策略与异策略的区别在于目标策略与行为策略是否一致。',['对','错'],0,
    p('答案为 A，对。行为策略（behavior policy，常记 b）负责产生数据；目标策略（target policy，常记 π）是被评估或改进的策略。') +
    ul('<b>同策略（on-policy）：</b>学习当前用于产生经验的策略。经典 SARSA 通常用当前 ε-greedy 策略采样，也在目标中使用该策略选出的下一动作。',
       '<b>异策略（off-policy）：</b>可用一种策略的数据学习另一种策略。Q-learning 可用带探索的行为策略采样，却以对 Q 的贪心选择构造目标。') +
    f('行为策略 b：怎样获得数据？<br>目标策略 π：这些更新在学习谁？') + p('这一区别不取决于数据来自真实环境还是模拟器，也不等同于“是否随机”“是否在线”。'),
    '同策略也会变化；异策略也可以暂时相同',p('控制过程中，on-policy 的策略可以随着价值估计改变；“同”指采样与学习所针对的策略一致，不是整个训练永远固定一个策略。Off-policy 方法允许两者不同，并不要求它们在每个时刻、每个状态都不同。') +
    p('从行为策略的数据评估目标策略时，需要数据覆盖目标策略会选择的动作。重要性采样是一种校正分布差异的方式，但并非所有异策略算法都显式使用重要性权重，例如标准一步 Q-learning。')),
    (5,3,'Q-learning 的基本性质','下列关于 Q-Learning 的说法中，哪一个是正确的？',
    ['Q-Learning 算法是一种基于模型的强化学习算法。','Q-Learning 算法可以用于解决连续状态和动作空间的问题。','Q-Learning 算法使用 ε-贪心策略来平衡探索和利用。','Q-Learning 算法使用蒙特卡罗方法来更新 Q 值。'],2,
    '<p class="note">建议选 C，按经典表格型 Q-learning 与常见 ε-greedy 实现理解。ε-greedy 是常用选择，并不是 Q-learning 定义强制规定的唯一行为策略。</p>' +
    p('Q-learning 直接从转移经验更新动作价值，使用下一状态的最大估计动作价值进行自举：') + f(ql) +
    ul('<b>A 错：</b>标准 Q-learning 是无模型 TD 控制算法，不需要显式转移概率。',
       '<b>B 不符合本题的标准表格语境：</b>普通 Q 表不能直接枚举无限的连续状态与动作。连续问题需要离散化、函数近似或其他扩展，不能不加条件地套用表格算法。',
       '<b>C 对：</b>常用 ε-greedy 行为策略保留随机探索，同时利用当前 Q 值选择贪心动作。',
       '<b>D 错：</b>其标准一步更新是 TD 更新，不需要等待完整回报，因而不是蒙特卡洛更新。'),
    '连续状态与连续动作是两种不同的难点',p('函数近似可以让 Q(s,a) 接收连续状态，例如常见 DQN 处理连续或高维状态但使用离散动作。连续动作还需要计算 maxₐ Q(s′,a)，往往涉及额外优化或策略网络。') +
    p('所以不能说所有 Q-learning 扩展都无法处理连续空间，也不能把扩展能力直接归给普通 Q 表。探索可用 ε-greedy 或其他满足任务需要的方法；收敛分析还需要充分访问和合适步长等条件。')),
    (5,4,'Q-learning 的后继状态价值','Q-Learning 中，TD 目标的后继状态的价值是如何计算的？',
    ['所有动作的平均价值','最优动作的价值','最差动作的价值','完整采样的实际奖励'],1,
    p('答案为 B。Q-learning 取下一状态所有可选动作的 Q 估计最大值。这里“最优动作”指当前估计下的贪心动作，并不是已经知道真实的最优动作。') +
    f('y<sub>t</sub> = R<sub>t+1</sub> + γ max<sub>a</sub> Q(S<sub>t+1</sub>,a)') +
    p('假设下一状态的两个动作价值估计为 5 和 2，即时奖励为 1，γ = 0.9，则后继价值取 5，TD 目标为 1 + 0.9 × 5 = 5.5。若当前 Q = 3，α = 0.1，更新后为 3 + 0.1 × (5.5 − 3) = 3.25。') +
    ul('A：不是简单对所有动作做平均；Expected SARSA 才会按目标策略的动作概率加权求期望，且通常不是均匀平均。','C：标准奖励最大化问题使用 max，而不是 min。','D：完整采样回报是 MC 的目标，不是这里的后继状态价值。'),
    '终止状态与最大化偏差',p('若下一状态是真正的终止状态，不再计算后续收益，目标取即时奖励 Rₜ₊₁。若只是外部时间限制导致采样截断、任务本身尚未终止，是否继续自举需依据任务定义，不能混为一谈。') +
    p('对带噪声的多个 Q 估计取最大值可能产生高估，即最大化偏差。Double Q-learning 的思路是分开动作选择与价值评估，以减少这种偏差。')),
    (5,5,'SARSA 中的 S','SARSA 算法中的“S”代表什么？',['State','Score','Strategy','Sequence'],0,
    p('答案为 A，State（状态）。SARSA 来自一次更新涉及的五个量：State、Action、Reward、State、Action。两个 S 分别表示当前状态和下一状态。') +
    f('(S<sub>t</sub>, A<sub>t</sub>, R<sub>t+1</sub>, S<sub>t+1</sub>, A<sub>t+1</sub>)') + f(sarsa) +
    p('与 Q-learning 不同，SARSA 的目标使用当前行为策略在下一状态实际选出的 Aₜ₊₁，而不是直接对下一状态的所有动作取最大值。Score 是得分，Strategy 是策略，Sequence 是序列，均不是缩写中 S 的含义。'),
    '同一次转移，两个算法的目标可以不同',p('沿用上一题：下一状态的 Q 估计为 5 和 2。若探索选到了价值估计为 2 的动作，SARSA 目标为 1 + 0.9 × 2 = 2.8；Q-learning 的目标仍为 5.5。当前 Q = 3、α = 0.1 时，SARSA 更新到 2.98，而 Q-learning 更新到 3.25。') +
    p('这说明 SARSA 的目标会计入当前探索策略可能采取的动作；若下一动作恰好也是贪心动作，两种算法在该步的目标可能相同。终止时不需要再选择下一动作，目标直接取奖励。')),
    (5,6,'识别蒙特卡洛控制算法','下列哪些是蒙特卡洛控制算法？',['SARSA','Q-Learning','遗传算法','蒙特卡洛策略迭代'],3,
    p('答案为 D，蒙特卡洛策略迭代。题干虽写“哪些”，截图使用单选圆形控件，且四个选项中只有 D 符合。') +
    f('按策略采集完整回合 → 用回报评估 Q → 提升策略并保留探索 → 重复') +
    ul('A：标准一步 SARSA 是同策略 TD 控制，用后继状态—动作价值自举。','B：标准一步 Q-learning 是异策略 TD 控制，用下一状态最大 Q 值自举。','C：遗传算法是进化优化方法。可以用于搜索策略，但它本身不是 MC 控制算法。','D：MC 策略迭代利用完整回报进行策略评估，再进行策略提升，属于 MC 控制。'),
    '“预测”与“控制”不是一回事',p('MC 预测是在给定策略下估计 V<sup>π</sup> 或 Q<sup>π</sup>；MC 控制还要利用价值估计改进策略。一般需要保持足够探索，例如探索性起步、ε-soft 策略，或满足相应条件的探索安排。') +
    p('不能仅因一个算法使用随机采样就把它归入这里的蒙特卡洛控制。应看它是否采用完整采样回报评估价值，以及是否据此进行控制。')),
    (5,7,'MC 与 TD 的共同点','MC 和 TD 有哪些共同点？',
    ['MC 方法和 TD 方法都可以用于求解价值函数','MC 方法和 TD 方法都可以直接从经验中学习，不需要先对环境建立模型','MC 方法和 TD(0) 都需要等到整个序列结束才能计算回报','MC 方法和 TD(0) 都不需要等到整个序列结束才能计算回报'],(0,1),
    p('答案为 A、B。经典 MC 与 TD 都能从采样经验估计价值，且都不要求先建立显式环境模型。两者关键区别在于更新目标与更新时机。') +
    f('MC 目标：G<sub>t</sub> = R<sub>t+1</sub> + γR<sub>t+2</sub> + ⋯ + γ<sup>T−t−1</sup>R<sub>T</sub><br>TD(0) 目标：R<sub>t+1</sub> + γV(S<sub>t+1</sub>)') +
    ul('<b>A 对：</b>两者都可用于估计状态价值；相应控制方法也可估计动作价值。','<b>B 对：</b>两者都可以直接从经验学习，是经典无模型方法。','<b>C 错：</b>TD(0) 不必等待完整回合结束就能更新。','<b>D 错：</b>经典完整回合 MC 要等回合结束后才获得完整采样回报。') +
    '<p class="note">原题 C、D 使用“计算回报”一词。准确地说，TD 是提前构造自举目标并更新价值，并没有提前获知完整实际回报。完整回报与 TD 目标应分开理解。</p>',
    'n-step TD：连接一步 TD 与完整回报',f('G<sub>t:t+n</sub> = ∑<sub>k=0</sub><sup>n−1</sup> γ<sup>k</sup>R<sub>t+k+1</sub> + γ<sup>n</sup>V(S<sub>t+n</sub>)') +
    p('上式适用于 n 步内尚未终止的情形。n = 1 是一步 TD；若回合在 n 步内结束，则累积到终止并去掉终止后的自举项，从而得到这段完整回报。n-step 方法体现了使用更长样本与更多自举之间的折中。')),
    (5,8,'识别无模型强化学习方法','下列哪些是无模型强化学习方法？',['策略迭代','价值迭代','Q-Learning','SARSA'],(2,3),
    p('答案为 C、D。本题将未加限定的“策略迭代”和“价值迭代”理解为作业 3 中经典的基于已知模型的动态规划算法。Q-learning 与 SARSA 则直接从转移经验进行 TD 更新。') +
    ul('<b>A、B 不选：</b>经典 DP 策略迭代与价值迭代需要转移概率和奖励模型，进行期望计算。','<b>C 选：</b>Q-learning 用经验奖励与后继最大 Q 估计构造目标，无需显式环境模型。','<b>D 选：</b>SARSA 用经验中的状态、动作、奖励及下一状态、下一动作更新 Q，也无需显式模型。') +
    '<p class="note">这与第 6 题并不矛盾：“策略迭代”也是一种评估—提升框架。若明确指蒙特卡洛策略迭代，它可以是无模型的；本题 A 指经典 DP 版本。</p>',
    '两条独立的分类轴',p('“有模型 / 无模型”关注是否使用环境转移与奖励模型进行规划；“同策略 / 异策略”关注采样策略与学习目标策略的关系。这是不同维度，不能互相替代。') +
    p('SARSA 通常是无模型、同策略；Q-learning 是无模型、异策略。“无模型”不表示没有 Q 表、神经网络或价值函数，这里的模型特指环境动力学及奖励模型。')),
    ]

RECAP = '''<section id="td-recap"><div class="eyebrow">TEMPORAL DIFFERENCE / 复习卡</div><h2>看更新目标，区分学习方法</h2><table><caption>MC、SARSA 与 Q-learning</caption><thead><tr><th>方法</th><th>典型目标</th><th>自举</th><th>策略关系</th></tr></thead><tbody><tr><td>MC 评估</td><td>完整回报 Gₜ</td><td>否</td><td>有同策略与异策略形式</td></tr><tr><td>SARSA</td><td>Rₜ₊₁ + γQ(Sₜ₊₁,Aₜ₊₁)</td><td>是</td><td>经典形式为同策略</td></tr><tr><td>Q-learning</td><td>Rₜ₊₁ + γ maxₐ Q(Sₜ₊₁,a)</td><td>是</td><td>异策略</td></tr><tr><td>Expected SARSA</td><td>Rₜ₊₁ + γ∑ₐ π(a|Sₜ₊₁)Q(Sₜ₊₁,a)</td><td>是</td><td>取决于目标与行为策略</td></tr></tbody></table><p>上表目标用于非终止转移；真正终止时去掉未来价值项。Expected SARSA 的求和是按策略概率加权，不一定是动作均匀平均。</p><div class="concepts"><p><b>是否有模型？</b><br>看是否依赖环境转移、奖励模型</p><p><b>是否自举？</b><br>看目标是否包含已有价值估计</p><p><b>同策略还是异策略？</b><br>看采样与学习针对的策略</p></div><table><caption>作业 5 · 易考判断</caption><thead><tr><th>说法</th><th>判断与条件</th></tr></thead><tbody><tr><td>TD(0) 必须等完整回合结束才能更新</td><td>错</td></tr><tr><td>MC 与 TD 都可直接从经验估计价值</td><td>对</td></tr><tr><td>Q-learning 是无模型、异策略 TD 控制</td><td>对</td></tr><tr><td>SARSA 的 S 指 State</td><td>对</td></tr><tr><td>Q-learning 的后继价值取所有动作的均值</td><td>错；取最大估计 Q 值</td></tr><tr><td>Q-learning 必须且只能使用 ε-greedy</td><td>错；它是常见行为策略</td></tr><tr><td>使用神经网络就属于有模型强化学习</td><td>错；价值网络不等于环境模型</td></tr><tr><td>普通 Q 表能直接枚举连续状态与动作</td><td>错；需要离散化或扩展</td></tr><tr><td>同策略的策略在训练中不能改变</td><td>错</td></tr></tbody></table><p>题目来源：用户提供的八张截图；按显示顺序标记选项。第 7、8 题为多选，第 6 题按截图单选处理。答案与解析为独立解答，非官方答案。参考：<a href="https://www.incompleteideas.net/book/bookdraft2018mar21.pdf">Sutton &amp; Barto，第 6 章 Temporal-Difference Learning</a>，尤其第 6.4–6.6 节；MC 控制参见第 5 章。</p></section>'''
